import java.util.*;

public class Main {
    static int[] processQueries(int[] queries, int m) {
        List<Integer> P = new ArrayList<>();
        for (int i = 1; i <= m; i++) P.add(i);
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int idx = P.indexOf(queries[i]);   // linear search for the value
            result[i] = idx;
            P.remove(idx);
            P.add(0, queries[i]);              // move to front
        }
        return result;
    }
}

