#include <bits/stdc++.h>
using namespace std;

vector<int> processQueries(vector<int>& queries, int m) {
    vector<int> P(m);
    for (int i = 0; i < m; i++) P[i] = i + 1;
    vector<int> result;
    for (int q : queries) {
        int idx = find(P.begin(), P.end(), q) - P.begin();   // linear search
        result.push_back(idx);
        P.erase(P.begin() + idx);
        P.insert(P.begin(), q);                                // move to front
    }
    return result;
}

